namespace ContosoDashboard.Services;

public interface IFileStorageService
{
    // storagePath is a relative, forward-slash path generated by the caller: {userId}/{projectId|personal}/{guid}.{ext}
    Task<string> UploadAsync(Stream content, string storagePath, string contentType, CancellationToken ct = default);

    // No error if the file is already gone
    Task DeleteAsync(string storagePath, CancellationToken ct = default);

    // Throws FileNotFoundException if the file is missing
    Task<Stream> DownloadAsync(string storagePath, CancellationToken ct = default);

    // Local implementation returns the storage path (not browsable); cloud implementations return a time-limited URL
    Task<string> GetUrlAsync(string storagePath, TimeSpan expiration);
}
